pub fn init_database(config: DatabaseConfig) -> Connection {
  let connection_config =
    pgo.Config(
      host: config.host,
      port: config.port,
      database: config.database,
      user: config.username,
      password: Some(config.password),
      ssl: False,
      pool_size: 10,
      queue_target: 50,
      queue_interval: 1000,
      idle_interval: 1000,
    )

  let assert Ok(conn) = pgo.connect(connection_config)

  let _ = execute_query(conn, "CREATE TABLE IF NOT EXISTS users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(64) UNIQUE NOT NULL,
    email VARCHAR(120) UNIQUE NOT NULL,
    password_hash VARCHAR(256) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    erste_customer_id VARCHAR(128),
    consent_id VARCHAR(128),
    access_token TEXT,
    refresh_token TEXT,
    token_expires_at TIMESTAMP
  )", [])

  let _ = execute_query(conn, "CREATE TABLE IF NOT EXISTS payments (
    id SERIAL PRIMARY KEY,
    payment_id VARCHAR(128) UNIQUE NOT NULL,
    user_id INTEGER REFERENCES users(id) NOT NULL,
    amount NUMERIC(10, 2) NOT NULL,
    currency VARCHAR(3) DEFAULT 'HUF' NOT NULL,
    status VARCHAR(20) DEFAULT 'pending' NOT NULL,
    payment_method VARCHAR(20) NOT NULL,
    recipient_name VARCHAR(128),
    recipient_iban VARCHAR(34),
    description TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    executed_at TIMESTAMP,
    erste_payment_id VARCHAR(128),
    transaction_id VARCHAR(128)
  )", [])

  let _ = execute_query(conn, "CREATE TABLE IF NOT EXISTS payment_links (
    id SERIAL PRIMARY KEY,
    link_id VARCHAR(128) UNIQUE NOT NULL,
    user_id INTEGER REFERENCES users(id) NOT NULL,
    amount NUMERIC(10, 2) NOT NULL,
    currency VARCHAR(3) DEFAULT 'HUF' NOT NULL,
    description TEXT,
    expires_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    used_at TIMESTAMP,
    is_active BOOLEAN DEFAULT TRUE,
    max_uses INTEGER DEFAULT 1,
    current_uses INTEGER DEFAULT 0
  )", [])

  let _ = execute_query(conn, "CREATE TABLE IF NOT EXISTS accounts (
    id SERIAL PRIMARY KEY,
    user_id INTEGER REFERENCES users(id) NOT NULL,
    account_id VARCHAR(128) UNIQUE NOT NULL,
    iban VARCHAR(34),
    name VARCHAR(128),
    currency VARCHAR(3) DEFAULT 'HUF',
    balance NUMERIC(10, 2),
    available_balance NUMERIC(10, 2),
    account_type VARCHAR(20),
    status VARCHAR(20) DEFAULT 'active',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP
  )", [])

  let _ = execute_query(conn, "CREATE TABLE IF NOT EXISTS transactions (
    id SERIAL PRIMARY KEY,
    transaction_id VARCHAR(128) UNIQUE NOT NULL,
    user_id INTEGER REFERENCES users(id) NOT NULL,
    account_id VARCHAR(128),
    amount NUMERIC(10, 2) NOT NULL,
    currency VARCHAR(3) DEFAULT 'HUF' NOT NULL,
    transaction_type VARCHAR(20) NOT NULL,
    counterpart_name VARCHAR(128),
    counterpart_iban VARCHAR(34),
    reference TEXT,
    booking_date TIMESTAMP,
    value_date TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
  )", [])

  conn
}

fn execute_query(conn: Connection, query: String, params: List(pgo.Value)) -> Result(pgo.Returned, pgo.QueryError) {
  pgo.execute(query, conn, params, decode.dynamic)
}

pub fn hash_password(password: String) -> String {
  crypto_hash("sha256", password)
}

@external(erlang, "crypto", "hash")
fn crypto_hash(algorithm: String, data: String) -> String

pub fn verify_password(password: String, hash: String) -> Bool {
  hash_password(password) == hash
}

pub fn generate_uuid() -> String {
  uuid_v4()
}

@external(erlang, "uuid", "uuid_to_string")
fn uuid_v4() -> String

pub fn middleware(req: WispRequest, state: AppState, handler: fn(WispRequest, AppState) -> WispResponse) -> WispResponse {
  let session_id = get_cookie(req, "session_id")

  case session_id {
    Some(sid) -> {
      case dict.get(state.sessions, sid) {
        Ok(_session) -> handler(req, state)
        Error(_) -> handler(req, state)
      }
    }
    None -> handler(req, state)
  }
}

fn get_cookie(req: WispRequest, name: String) -> Option(String) {
  case wisp.get_cookie(req, name, security.Signed) {
    Ok(value) -> Some(value)
    Error(_) -> None
  }
}

fn set_cookie(resp: WispResponse, name: String, value: String, max_age: Int) -> WispResponse {
  wisp.set_cookie(resp, name, value, security.Signed, max_age)
}

pub fn router(req: WispRequest, state: AppState) -> WispResponse {
  case wisp.path_segments(req) {
    [] -> index_handler(req, state)
    ["auth", "login"] -> login_handler(req, state)
    ["auth", "register"] -> register_handler(req, state)
    ["auth", "logout"] -> logout_handler(req, state)
    ["auth", "erste"] -> erste_auth_handler(req, state)
    ["auth", "callback"] -> auth_callback_handler(req, state)
    ["dashboard"] -> dashboard_handler(req, state)
    ["payment", "create"] -> create_payment_handler(req, state)
    ["payment", "link", "create"] -> create_payment_link_handler(req, state)
    ["payment", "status", payment_id] -> payment_status_handler(req, state, payment_id)
    ["pay", link_id] -> pay_via_link_handler(req, state, link_id)
    ["transactions"] -> transaction_history_handler(req, state)
    ["api", "accounts", "refresh"] -> refresh_accounts_handler(req, state)
    ["api", "payout", "instant"] -> instant_payout_handler(req, state)
    ["api", "apple-pay", "validate-merchant"] -> apple_pay_validate_handler(req, state)
    ["api", "apple-pay", "process-payment"] -> apple_pay_process_handler(req, state)
    ["api", "google-pay", "process-payment"] -> google_pay_process_handler(req, state)
    _ -> wisp.not_found()
  }
}

