fn login_handler(req: WispRequest, state: AppState) -> WispResponse {
  case req.method {
    http.Get -> {
      let html = "<!DOCTYPE html>
<html lang=\"hu\">
<head>
    <meta charset=\"UTF-8\">
    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">
    <title>Bejelentkezés - TiffyTime</title>
</head>
<body>
    <h1>Bejelentkezés</h1>
    <form method=\"POST\">
        <label>Felhasználónév: <input type=\"text\" name=\"username\" required></label><br>
        <label>Jelszó: <input type=\"password\" name=\"password\" required></label><br>
        <button type=\"submit\">Bejelentkezés</button>
    </form>
    <p>Nincs még fiókod? <a href=\"/auth/register\">Regisztrálj itt</a></p>
</body>
</html>"

      wisp.html_response(html, 200)
    }
    http.Post -> {
      use form_data <- wisp.require_form(req)

      let username = get_form_value(form_data.values, "username")
      let password = get_form_value(form_data.values, "password")

      case username, password {
        Some(u), Some(p) -> {
          case find_user_by_username(state.db, u) {
            Ok(user) -> {
              case verify_password(p, user.password_hash) {
                True -> {
                  let session_id = generate_uuid()
                  let session = Session(user.id, user.username, user.email, generate_uuid())
                  let new_sessions = dict.insert(state.sessions, session_id, session)
                  let new_state = AppState(..state, sessions: new_sessions)

                  let resp = wisp.redirect("/dashboard")
                  set_cookie(resp, "session_id", session_id, 86400)
                }
                False -> wisp.redirect("/auth/login?error=invalid")
              }
            }
            Error(_) -> wisp.redirect("/auth/login?error=invalid")
          }
        }
        _, _ -> wisp.redirect("/auth/login?error=missing")
      }
    }
    _ -> wisp.method_not_allowed([http.Get, http.Post])
  }
}

