fn logout_handler(_req: WispRequest, _state: AppState) -> WispResponse {
  let resp = wisp.redirect("/")
  set_cookie(resp, "session_id", "", 0)
}

fn dashboard_handler(req: WispRequest, state: AppState) -> WispResponse {
  case get_current_user(req, state) {
    Some(user) -> {
      case get_user_payments(state.db, user.id, 10) {
        Ok(payments) -> {
          case get_user_accounts(state.db, user.id) {
            Ok(accounts) -> {
              case get_user_payment_links(state.db, user.id) {
                Ok(links) -> {
                  let html = render_dashboard(user, payments, accounts, links)
                  wisp.html_response(html, 200)
                }
                Error(_) -> wisp.internal_server_error()
              }
            }
            Error(_) -> wisp.internal_server_error()
          }
        }
        Error(_) -> wisp.internal_server_error()
      }
    }
    None -> wisp.redirect("/auth/login")
  }
}

fn create_payment_handler(req: WispRequest, state: AppState) -> WispResponse {
  case get_current_user(req, state) {
    Some(user) -> {
      case req.method {
        http.Get -> {
          case get_user_accounts(state.db, user.id) {
            Ok(accounts) -> {
              let html = render_create_payment(accounts)
              wisp.html_response(html, 200)
            }
            Error(_) -> wisp.internal_server_error()
          }
        }
        http.Post -> {
          use form_data <- wisp.require_form(req)

          let payment_method = get_form_value(form_data.values, "payment_method")
          let amount = get_form_value(form_data.values, "amount")
          let currency = get_form_value(form_data.values, "currency")
          let recipient_name = get_form_value(form_data.values, "recipient_name")
          let recipient_iban = get_form_value(form_data.values, "recipient_iban")
          let debtor_iban = get_form_value(form_data.values, "debtor_iban")
          let description = get_form_value(form_data.values, "description")

          case payment_method, amount, currency, recipient_name {
            Some(pm), Some(amt), Some(cur), Some(rn) -> {
              case float.parse(amt) {
                Ok(amount_float) -> {
                  let payment_id = generate_uuid()

                  case create_payment(state.db, payment_id, user.id, amount_float, cur, pm, Some(rn), recipient_iban, description) {
                    Ok(_) -> {
                      case pm {
                        "erste" -> process_erste_payment(state, user, payment_id, amount_float, cur, rn, recipient_iban, debtor_iban, description)
                        "apple_pay" -> wisp.redirect("/dashboard?payment=apple_initiated")
                        "google_pay" -> wisp.redirect("/dashboard?payment=google_initiated")
                        _ -> wisp.redirect("/dashboard?error=invalid_method")
                      }
                    }
                    Error(_) -> wisp.redirect("/payment/create?error=failed")
                  }
                }
                Error(_) -> wisp.redirect("/payment/create?error=invalid_amount")
              }
            }
            _, _, _, _ -> wisp.redirect("/payment/create?error=missing")
          }
        }
        _ -> wisp.method_not_allowed([http.Get, http.Post])
      }
    }
    None -> wisp.redirect("/auth/login")
  }
}

fn create_payment_link_handler(req: WispRequest, state: AppState) -> WispResponse {
  case get_current_user(req, state) {
    Some(user) -> {
      case req.method {
        http.Get -> {
          let html = render_create_payment_link()
          wisp.html_response(html, 200)
        }
        http.Post -> {
          use form_data <- wisp.require_form(req)

          let amount = get_form_value(form_data.values, "amount")
          let currency = get_form_value(form_data.values, "currency")
          let description = get_form_value(form_data.values, "description")
          let max_uses = get_form_value(form_data.values, "max_uses")

          case amount, currency {
            Some(amt), Some(cur) -> {
              case float.parse(amt) {
                Ok(amount_float) -> {
                  let link_id = generate_uuid()
                  let max_uses_int = case max_uses {
                    Some(mu) -> case int.parse(mu) {
                      Ok(i) -> i
                      Error(_) -> 1
                    }
                    None -> 1
                  }

                  case create_payment_link_db(state.db, link_id, user.id, amount_float, cur, description, max_uses_int) {
                    Ok(_) -> wisp.redirect("/dashboard?link_created=true")
                    Error(_) -> wisp.redirect("/payment/link/create?error=failed")
                  }
                }
                Error(_) -> wisp.redirect("/payment/link/create?error=invalid_amount")
              }
            }
            _, _ -> wisp.redirect("/payment/link/create?error=missing")
          }
        }
        _ -> wisp.method_not_allowed([http.Get, http.Post])
      }
    }
    None -> wisp.redirect("/auth/login")
  }
}

fn payment_status_handler(req: WispRequest, state: AppState, payment_id: String) -> WispResponse {
  case get_current_user(req, state) {
    Some(_user) -> {
      case get_payment_by_id(state.db, payment_id) {
        Ok(payment) -> {
          let json_response = json.object([
            #("success", json.bool(True)),
            #("payment_id", json.string(payment.payment_id)),
            #("status", json.string(payment.status)),
            #("amount", json.float(payment.amount)),
            #("currency", json.string(payment.currency)),
          ])

          wisp.json_response(json.to_string(json_response), 200)
        }
        Error(_) -> {
          let error_json = json.object([
            #("success", json.bool(False)),
            #("error", json.string("Payment not found")),
          ])

          wisp.json_response(json.to_string(error_json), 404)
        }
      }
    }
    None -> wisp.response(401)
  }
}

fn pay_via_link_handler(req: WispRequest, state: AppState, link_id: String) -> WispResponse {
  case req.method {
    http.Get -> {
      case get_payment_link(state.db, link_id) {
        Ok(link) -> {
          case link.is_active {
            True -> {
              let html = render_pay_link(link)
              wisp.html_response(html, 200)
            }
            False -> {
              let html = "<html><body><h1>A fizetési link már nem aktív</h1></body></html>"
              wisp.html_response(html, 400)
            }
          }
        }
        Error(_) -> wisp.not_found()
      }
    }
    http.Post -> {
      use json_body <- wisp.require_json(req)

      case get_payment_link(state.db, link_id) {
        Ok(link) -> {
          case link.is_active && link.current_uses < link.max_uses {
            True -> {
              let payment_id = generate_uuid()

              case create_payment(state.db, payment_id, link.user_id, link.amount, link.currency, "erste", None, None, link.description) {
                Ok(_) -> {
                  let _ = increment_payment_link_usage(state.db, link_id)

                  let response_json = json.object([
                    #("success", json.bool(True)),
                    #("redirect_url", json.string("/payment/success?payment_id=" <> payment_id)),
                  ])

                  wisp.json_response(json.to_string(response_json), 200)
                }
                Error(_) -> {
                  let error_json = json.object([
                    #("success", json.bool(False)),
                    #("error", json.string("Failed to create payment")),
                  ])

                  wisp.json_response(json.to_string(error_json), 500)
                }
              }
            }
            False -> {
              let error_json = json.object([
                #("success", json.bool(False)),
                #("error", json.string("Payment link expired or max uses reached")),
              ])

              wisp.json_response(json.to_string(error_json), 400)
            }
          }
        }
        Error(_) -> wisp.not_found()
      }
    }
    _ -> wisp.method_not_allowed([http.Get, http.Post])
  }
}

fn transaction_history_handler(req: WispRequest, state: AppState) -> WispResponse {
  case get_current_user(req, state) {
    Some(user) -> {
      case get_user_payments(state.db, user.id, 50) {
        Ok(payments) -> {
          case get_user_transactions(state.db, user.id) {
            Ok(transactions) -> {
              let html = render_transaction_history(payments, transactions)
              wisp.html_response(html, 200)
            }
            Error(_) -> wisp.internal_server_error()
          }
        }
        Error(_) -> wisp.internal_server_error()
      }
    }
    None -> wisp.redirect("/auth/login")
  }
}

fn erste_auth_handler(req: WispRequest, state: AppState) -> WispResponse {
  case get_current_user(req, state) {
    Some(user) -> {
      case create_erste_consent(state.erste_config) {
        Ok(consent_data) -> {
          case dict.get(consent_data, "consentId") {
            Ok(consent_id_json) -> {
              let consent_id = json.to_string(consent_id_json)
              let _ = update_user_consent(state.db, user.id, consent_id)

              let auth_url = build_erste_auth_url(state.erste_config, consent_id)
              wisp.redirect(auth_url)
            }
            Error(_) -> wisp.redirect("/dashboard?error=consent_failed")
          }
        }
        Error(_) -> wisp.redirect("/dashboard?error=erste_failed")
      }
    }
    None -> wisp.redirect("/auth/login")
