fn auth_callback_handler(req: WispRequest, state: AppState) -> WispResponse {
  case get_current_user(req, state) {
    Some(user) -> {
      let query_params = uri.parse_query(wisp.get_query(req))

      case dict.get(query_params, "code"), dict.get(query_params, "state") {
        Ok(code), Ok(state_param) -> {
          case exchange_erste_token(state.erste_config, code, state_param) {
            Ok(token_data) -> {
              case dict.get(token_data, "access_token"), dict.get(token_data, "refresh_token") {
                Ok(access_token_json), Ok(refresh_token_json) -> {
                  let access_token = json.to_string(access_token_json)
                  let refresh_token = json.to_string(refresh_token_json)

                  let _ = update_user_tokens(state.db, user.id, access_token, refresh_token)

                  case get_erste_accounts(state.erste_config, access_token) {
                    Ok(accounts_data) -> {
                      let _ = save_user_accounts(state.db, user.id, accounts_data)
                      wisp.redirect("/dashboard?erste_connected=true")
                    }
                    Error(_) -> wisp.redirect("/dashboard?error=accounts_failed")
                  }
                }
                _, _ -> wisp.redirect("/dashboard?error=token_missing")
              }
            }
            Error(_) -> wisp.redirect("/dashboard?error=token_exchange_failed")
          }
        }
        _, _ -> wisp.redirect("/dashboard?error=missing_params")
      }
    }
    None -> wisp.redirect("/auth/login")
  }
}

