pub fn main() {
  let db_config = database_config_from_env()
  let erste_config = erste_config_from_env()
  let secret_key = get_env_or("SESSION_SECRET", "development_secret_key_change_in_production")

  let db = init_database(db_config)
  let initial_state = AppState(db, erste_config, dict.new(), secret_key)

  let handler = fn(req) { middleware(req, initial_state, router) }

  let assert Ok(_) = wisp.run(handler, 8000)

  process.sleep_forever()
}


